// src/core/world/services/world.service.ts
import { CountryRepository } from '../repositories/country.repository';
import { StateRepository } from '../repositories/state.repository';
import { CityRepository } from '../repositories/city.repository';
import { CountryModel } from '../models/country.model';
import { StateModel } from '../models/state.model';
import { CityModel } from '../models/city.model';
import { BadRequestError } from '@core/errors';
import type { Country, State, City, CityFullPath } from '../world.types';

class WorldService {
  private countryRepo = new CountryRepository();
  private stateRepo = new StateRepository();
  private cityRepo = new CityRepository();

  /**
   * Lista todos os países
   */
  async getCountries(): Promise<Country[]> {
    const rows = await this.countryRepo.findAll();
    return CountryModel.fromRows(rows);
  }

  /**
   * Busca país por ID
   */
  async getCountryById(countryId: string): Promise<Country | null> {
    const row = await this.countryRepo.findById(countryId);
    return row ? CountryModel.fromRow(row) : null;
  }

  /**
   * Busca país por código ISO
   */
  async getCountryByCode(code: string): Promise<Country | null> {
    const row = await this.countryRepo.findByCode(code);
    return row ? CountryModel.fromRow(row) : null;
  }

  /**
   * Lista todos os estados de um país
   */
  async getStatesByCountry(countryId: string): Promise<State[]> {
    const rows = await this.stateRepo.findByCountryId(countryId);
    return StateModel.fromRows(rows);
  }

  /**
   * Busca estado por ID
   */
  async getStateById(stateId: string): Promise<State | null> {
    const row = await this.stateRepo.findById(stateId);
    return row ? StateModel.fromRow(row) : null;
  }

  /**
   * Lista todas as cidades de um estado
   */
  async getCitiesByState(stateId: string): Promise<City[]> {
    const rows = await this.cityRepo.findByStateId(stateId);
    return CityModel.fromRows(rows);
  }

  /**
   * Busca cidade por ID
   */
  async getCityById(cityId: string): Promise<City | null> {
    const row = await this.cityRepo.findById(cityId);
    return row ? CityModel.fromRow(row) : null;
  }

  /**
   * Busca cidades por termo
   */
  async searchCities(
    term: string,
    options?: {
      countryId?: string;
      stateId?: string;
      limit?: number;
      offset?: number;
    }
  ): Promise<City[]> {
    const limit = options?.limit ?? 20;
    const offset = options?.offset ?? 0;
    const rows = await this.cityRepo.search(
      term,
      options?.countryId,
      options?.stateId,
      limit,
      offset
    );
    return CityModel.fromRows(rows);
  }

  /**
   * Busca caminho completo de uma cidade (cidade → estado → país)
   */
  async getCityFullPath(cityId: string): Promise<CityFullPath | null> {
    const city = await this.getCityById(cityId);
    if (!city) {
      return null;
    }

    const state = await this.getStateById(city.stateId);
    if (!state) {
      return null;
    }

    const country = await this.getCountryById(state.countryId);
    if (!country) {
      return null;
    }

    return {
      city: {
        cityId: city.cityId,
        name: city.name,
        nameEn: city.nameEn,
      },
      state: {
        stateId: state.stateId,
        name: state.name,
        nameEn: state.nameEn,
        code: state.code,
      },
      country: {
        countryId: country.countryId,
        name: country.name,
        nameEn: country.nameEn,
        code: country.code,
      },
    };
  }

  /**
   * Valida hierarquia de localização (país → estado → cidade)
   * 🔴 VALIDAÇÃO FORTE: Garante consistência hierárquica
   * 
   * Regras:
   * - Se cityId existir → validar stateId
   * - Se stateId existir → validar countryId
   * - Se faltar nível intermediário → erro claro
   * 
   * @param countryId - ID do país (opcional)
   * @param stateId - ID do estado (opcional)
   * @param cityId - ID da cidade (opcional)
   * @throws BadRequestError se a hierarquia for inválida
   */
  async validateLocation(
    countryId?: string | null,
    stateId?: string | null,
    cityId?: string | null
  ): Promise<void> {
    // Se não há nenhuma localização, não precisa validar
    if (!countryId && !stateId && !cityId) {
      return;
    }

    // Se cityId existe, stateId é obrigatório
    if (cityId && !stateId) {
      throw new BadRequestError('state_id é obrigatório quando city_id é fornecido');
    }

    // Se stateId existe, countryId é obrigatório
    if (stateId && !countryId) {
      throw new BadRequestError('country_id é obrigatório quando state_id é fornecido');
    }

    // Validar país se fornecido
    if (countryId) {
      const country = await this.getCountryById(countryId);
      if (!country) {
        throw new BadRequestError('País não encontrado');
      }
    }

    // Validar estado se fornecido
    if (stateId) {
      const state = await this.getStateById(stateId);
      if (!state) {
        throw new BadRequestError('Estado não encontrado');
      }

      // Se countryId foi fornecido, verificar se estado pertence ao país
      if (countryId && state.countryId !== countryId) {
        throw new BadRequestError('Estado não pertence ao país especificado');
      }
    }

    // Validar cidade se fornecida
    if (cityId) {
      const city = await this.getCityById(cityId);
      if (!city) {
        throw new BadRequestError('Cidade não encontrada');
      }

      // Se stateId foi fornecido, verificar se cidade pertence ao estado
      if (stateId && city.stateId !== stateId) {
        throw new BadRequestError('Cidade não pertence ao estado especificado');
      }

      // Buscar estado da cidade para validações adicionais
      const cityState = await this.getStateById(city.stateId);
      if (!cityState) {
        throw new BadRequestError('Estado da cidade não encontrado');
      }

      // Se countryId foi fornecido, verificar se estado da cidade pertence ao país
      if (countryId && cityState.countryId !== countryId) {
        throw new BadRequestError('Cidade não pertence ao país especificado');
      }
    }
  }
}

export const worldService = new WorldService();

